CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', age integer NOT NULL DEFAULT 15, sex text NOT NULL DEFAULT 'Maschio', height numeric NOT NULL DEFAULT 170, initial_weight numeric NOT NULL DEFAULT 123, preferences jsonb NOT NULL DEFAULT '{"excluded":[],"favorites":[],"theme":"light","reminders":{}}', professional_notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_owner ON public.profiles FOR ALL TO authenticated USING (id = (SELECT auth.uid())) WITH CHECK (id = (SELECT auth.uid()));
CREATE TABLE public.daily_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, date date NOT NULL, water integer NOT NULL DEFAULT 0 CHECK(water >= 0), sleep numeric NOT NULL DEFAULT 0 CHECK(sleep >= 0 AND sleep <= 24), mood text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', activity text NOT NULL DEFAULT '', duration integer NOT NULL DEFAULT 0 CHECK(duration >= 0), UNIQUE(user_id,date));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.daily_entries TO authenticated;
GRANT ALL ON public.daily_entries TO service_role;
ALTER TABLE public.daily_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY entries_owner ON public.daily_entries FOR ALL TO authenticated USING(user_id = (SELECT auth.uid())) WITH CHECK(user_id = (SELECT auth.uid()));
CREATE TABLE public.meal_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, date date NOT NULL, slot integer NOT NULL CHECK(slot BETWEEN 0 AND 4), dish_id text NOT NULL, completed boolean NOT NULL DEFAULT false, consumed text NOT NULL DEFAULT '', professional_portion text NOT NULL DEFAULT '', time text NOT NULL DEFAULT '', UNIQUE(user_id,date,slot));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.meal_entries TO authenticated;
GRANT ALL ON public.meal_entries TO service_role;
ALTER TABLE public.meal_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY meals_owner ON public.meal_entries FOR ALL TO authenticated USING(user_id = (SELECT auth.uid())) WITH CHECK(user_id = (SELECT auth.uid()));
CREATE TABLE public.workout_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, date date NOT NULL, title text NOT NULL, exercises text NOT NULL DEFAULT '', duration integer NOT NULL DEFAULT 0 CHECK(duration >= 0), notes text NOT NULL DEFAULT '', completed boolean NOT NULL DEFAULT false, UNIQUE(user_id,date));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.workout_entries TO authenticated;
GRANT ALL ON public.workout_entries TO service_role;
ALTER TABLE public.workout_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY workouts_owner ON public.workout_entries FOR ALL TO authenticated USING(user_id = (SELECT auth.uid())) WITH CHECK(user_id = (SELECT auth.uid()));
CREATE FUNCTION public.handle_mybalance_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES(NEW.id, COALESCE(NEW.raw_user_meta_data->>'name','')); RETURN NEW; END; $$;
CREATE TRIGGER mybalance_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_mybalance_signup();